mapper.select:
SELECT 
FROM stress_schedule
WHERE enabled = 1 AND next_run_time <= #{now}
ORDER BY next_run_time ASC
LIMIT #{limit}

mapper.update:
UPDATE stress_schedule
SET last_task_id = #{lastTaskId},
    last_run_time = #{lastRunTime},
    next_run_time = #{nextRunTime}
WHERE id = #{id} AND next_run_time = #{lastRunTime}
